content.content:
- label: Create a pie/donut chart - Console
  lang: Console_pie
  source: |
    POST kbn:/api/visualizations
    {
      "type": "pie",
      "title": "Requests by response code",
      "data_source": {
        "type": "data_view_spec",
        "index_pattern": "kibana_sample_data_logs",
        "time_field": "timestamp"
      },
      "metrics": [
        {
          "operation": "count"
        }
      ],
      "group_by": [
        {
          "operation": "terms",
          "fields": [
            "response.keyword"
          ],
          "limit": 5
        }
      ],
      "styling": {
        "donut_hole": "m"
      }
    }
- label: Create a data table - cURL
  lang: cURL_table
  source: |
    curl -X POST "${KIBANA_URL}/api/visualizations" \
      -H "Authorization: ApiKey ${API_KEY}" \
      -H "kbn-xsrf: true" \
      -H "Content-Type: application/json" \
      -d '{
      "type": "data_table",
      "title": "Top response codes",
      "data_source": {
        "type": "data_view_spec",
        "index_pattern": "kibana_sample_data_logs",
        "time_field": "timestamp"
      },
      "metrics": [
        {
          "operation": "count"
        }
      ],
      "rows": [
        {
          "operation": "terms",
          "fields": [
            "response.keyword"
          ],
          "limit": 5
        }
      ]
    }'
- label: Create a data table - Console
  lang: Console_table
  source: |
    POST kbn:/api/visualizations
    {
      "type": "data_table",
      "title": "Top response codes",
      "data_source": {
        "type": "data_view_spec",
        "index_pattern": "kibana_sample_data_logs",
        "time_field": "timestamp"
      },
      "metrics": [
        {
          "operation": "count"
        }
      ],
      "rows": [
        {
          "operation": "terms",
          "fields": [
            "response.keyword"
          ],
          "limit": 5
        }
      ]

