input.command:
cd /tmp/eff-vyfzuz4d/work; curl -s -X POST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H 'kbn-xsrf: true' -H 'Content-Type: application/json' "$KIBANA_URL/api/alerting/rule" -d '{
 "name": "EFF-2d4413e9 5xx spike",
 "rule_type_id": ".es-query",
 "consumer": "alerts",
 "schedule": {"interval": "1m"},
 "tags": ["web-logs"],
 "params": {
   "searchType": "searchSource",
   "searchConfiguration": {
     "index": "90943e30-9a47-11e8-b64d-95841ca0b247",
     "query": {"language": "kuery", "query": "response.keyword >= \"500\" and response.keyword < \"600\""}
   },
   "aggType": "count",
   "groupBy": "all",
   "threshold": [10],
   "thresholdComparator": ">",
   "timeWindowSize": 5,
   "timeWindowUnit": "m",
   "size": 100,
   "excludeHitsFromPreviousRun": false
 }
}' | python3 -m json.tool | head -40

